import sys
import requests
import json

def send_request(sid, method, params=None, msg_id=None):
    headers = {
        "mcp-session-id": sid,
        "Content-Type": "application/json",
        "Accept": "application/json, text/event-stream"
    }
    payload = {
        "jsonrpc": "2.0",
        "method": method
    }
    if params is not None:
        payload["params"] = params
    if msg_id is not None:
        payload["id"] = msg_id

    r = requests.post("http://are-sidecar:8000/mcp", headers=headers, json=payload, stream=True)
    for line in r.iter_lines():
        if line:
            line_str = line.decode('utf-8')
            if line_str.startswith("data: "):
                try:
                    return json.loads(line_str[6:])
                except:
                    pass
    return None

def main():
    if len(sys.argv) < 2:
        return
    r1 = requests.get("http://are-sidecar:8000/mcp", headers={"Accept": "text/event-stream"})
    sid = r1.headers.get("mcp-session-id")
    init_params = {
        "protocolVersion": "2024-11-05",
        "capabilities": {},
        "clientInfo": {"name": "test", "version": "1.0"}
    }
    send_request(sid, "initialize", init_params, 1)
    send_request(sid, "notifications/initialized", {})

    cmd = sys.argv[1]
    if cmd == "list":
        res = send_request(sid, "tools/list", {}, 2)
        tools = res.get("result", {}).get("tools", [])
        for t in tools:
            print(t["name"])
    else:
        args = json.loads(sys.argv[2]) if len(sys.argv) > 2 else {}
        res = send_request(sid, "tools/call", {
            "name": cmd,
            "arguments": args
        }, 3)
        print(json.dumps(res, indent=2))

if __name__ == "__main__":
    main()
